"use strict";

(function () {
  const DEFAULT_TITLE =
    "LÍNEA 3 / RECETA DE POSICIÓN FINAL DE VÁLVULAS";

  const DEFAULT_SUBTITLE =
    "Configuración de la posición de las válvulas al finalizar el proceso";

  const PRE_ESTIRO_LABELS = [
    "Entrada de Pre-Estiro",
    "Pre-Estiramiento",
    "Salida Pre-Estiro"
  ];

  const ESTIRO_LABELS = [
    "Entrada de Estiro",
    "Salida Estiramiento"
  ];

  let latestWidget = null;
  let headerObserver = null;

  function make(tag, className, parent, text) {
    const element = document.createElement(tag);
    element.className = className;

    if (text !== undefined) {
      element.textContent = text;
    }

    parent.appendChild(element);
    return element;
  }

  function makeRow(label, parent) {
    const row = make("div", "valve-row", parent);

    make("span", "valve-label", row, label);

    make(
      "div",
      "recipe-value recipe-value--editable",
      row
    ).setAttribute("aria-hidden", "true");

    make(
      "div",
      "valve-unit",
      row
    ).setAttribute("aria-hidden", "true");

    make(
      "div",
      "recipe-value recipe-value--applied",
      row
    ).setAttribute("aria-hidden", "true");
  }

  function fitHeader() {
    const entries = [
      [".recipe-title", 28],
      [".recipe-subtitle", 14]
    ];

    entries.forEach(function (entry) {
      const element = document.querySelector(entry[0]);

      if (!element || element.hidden) return;

      const baseSize = entry[1];
      element.style.fontSize = baseSize + "px";

      if (
        element.clientWidth > 0 &&
        element.scrollWidth > element.clientWidth
      ) {
        element.style.fontSize =
          (
            baseSize *
            element.clientWidth /
            element.scrollWidth
          ) + "px";
      }
    });
  }

  function updateHeader(widget) {
    const title = document.querySelector(".recipe-title");
    const subtitle = document.querySelector(".recipe-subtitle");

    if (!title || !subtitle) return;

    const name =
      widget && typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    const separator = name.indexOf("//");

    const customTitle =
      separator < 0
        ? name
        : name.slice(0, separator).trim();

    const customSubtitle =
      separator < 0
        ? DEFAULT_SUBTITLE
        : name.slice(separator + 2).trim();

    title.textContent = customTitle || DEFAULT_TITLE;
    subtitle.textContent = customSubtitle;
    subtitle.hidden = customSubtitle === "";

    fitHeader();
  }

  function buildWidget() {
    const preEstiro = document.getElementById("valve-group-pre");
    const estiro = document.getElementById("valve-group-estiro");

    if (!preEstiro || !estiro) return;

    preEstiro.replaceChildren();
    estiro.replaceChildren();

    PRE_ESTIRO_LABELS.forEach(function (label) {
      makeRow(label, preEstiro);
    });

    ESTIRO_LABELS.forEach(function (label) {
      makeRow(label, estiro);
    });

    updateHeader(latestWidget || window.WIDGET || null);

    const heading = document.querySelector(".recipe-heading");

    if (typeof ResizeObserver !== "undefined" && heading) {
      if (headerObserver) {
        headerObserver.disconnect();
      }

      headerObserver = new ResizeObserver(fitHeader);
      headerObserver.observe(heading);
    } else {
      window.addEventListener("resize", fitHeader);
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(fitHeader);
    }
  }

  /*
   * NOMBRE: Título//Subtítulo
   * Sin "//": cambia el título y conserva el subtítulo predeterminado.
   * Con "//" al final: oculta el subtítulo.
   *
   * Widget visual: no recibe tags del PLC ni ejecuta acciones.
   */
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    updateHeader(widget);
  };

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      buildWidget,
      { once: true }
    );
  } else {
    buildWidget();
  }
})();
